<script setup lang="ts">
import type { CrmCustomerListItemDto, CrmContactListItemDto, CrmOpportunityListItemDto, CrmSalesOrderCreateDto, CrmSalesOrderDetailDto, CrmSalesOrderListItemDto, CrmSalesOrderLineCreateDto, CrmSalesOrderLineDto } from '@/api'
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { createPageRequest, CrmSalesOrderStatus, crmSalesOrderApi, crmCustomerApi, crmContactApi, crmOpportunityApi } from '@/api'
import { toast } from '~/composables'
import { usePermission } from '~/hooks'
defineOptions({ name: 'CrmSalesOrderPage' })
const { t } = useI18n(); const { hasPermission } = usePermission()
const rows=ref<CrmSalesOrderListItemDto[]>([]); const lines=ref<CrmSalesOrderLineDto[]>([]); const loading=ref(false); const keyword=ref(''); const status=ref<CrmSalesOrderStatus|''>(''); const pageIndex=ref(1); const totalCount=ref(0); const pageSize=20; const selected=ref<CrmSalesOrderDetailDto|CrmSalesOrderListItemDto|null>(null)
const totalPages=computed(()=>Math.max(1,Math.ceil(totalCount.value/pageSize))); const canExecute=computed(()=>hasPermission('crm_sales_orders.execute'))

const canCreate=computed(()=>hasPermission('crm_sales_orders.create'))
const customerOptions=ref<CrmCustomerListItemDto[]>([]); const contactOptions=ref<CrmContactListItemDto[]>([]); const opportunityOptions=ref<CrmOpportunityListItemDto[]>([]); const customerSearch=ref(''); const loadingRelations=ref(false)
const createOpen=ref(false); const saving=ref(false)
const form=ref({orderNumber:'',customerId:'',contactId:'',opportunityId:'',orderDate:new Date().toISOString().slice(0,10),currency:'USD',customerPurchaseOrderNumber:'',paymentTerms:'',deliveryTerms:'',notes:''})
function newLine():CrmSalesOrderLineCreateDto{return {productCode:'',description:'',quantity:1,unit:'',unitPrice:0,discountRate:0,taxRate:0,sortOrder:0}}
const draftLines=ref<CrmSalesOrderLineCreateDto[]>([newLine()])
const previewTotal=computed(()=>draftLines.value.reduce((sum,line)=>{const subtotal=Math.round(line.quantity*line.unitPrice*100)/100;const discount=Math.round(subtotal*line.discountRate)/100;const tax=Math.round((subtotal-discount)*line.taxRate)/100;return sum+subtotal-discount+tax},0))
function addLine(){if(draftLines.value.length<500)draftLines.value.push({...newLine(),sortOrder:draftLines.value.length})}
function removeLine(index:number){if(draftLines.value.length>1)draftLines.value.splice(index,1)}
async function searchCustomers(){try{const p=createPageRequest({page:{pageIndex:1,pageSize:100}});const r=await crmCustomerApi.page({...p,keyword:customerSearch.value.trim()||null});customerOptions.value=r.items}catch(e){toast.danger((e as Error)?.message||t('crm.salesOrder.customerLoadError'))}}
async function loadCustomerRelations(customerId:string){contactOptions.value=[];opportunityOptions.value=[];form.value.contactId='';form.value.opportunityId='';if(!customerId)return;loadingRelations.value=true;try{const p=createPageRequest({page:{pageIndex:1,pageSize:100}});const [contacts,opportunities]=await Promise.all([crmContactApi.page({...p,customerId}),crmOpportunityApi.page({...p,customerId})]);contactOptions.value=contacts.items;opportunityOptions.value=opportunities.items}catch(e){toast.danger((e as Error)?.message||t('crm.salesOrder.relatedLoadError'))}finally{loadingRelations.value=false}}
async function openCreate(){form.value={orderNumber:'',customerId:'',contactId:'',opportunityId:'',orderDate:new Date().toISOString().slice(0,10),currency:'USD',customerPurchaseOrderNumber:'',paymentTerms:'',deliveryTerms:'',notes:''};draftLines.value=[newLine()];contactOptions.value=[];opportunityOptions.value=[];customerSearch.value='';createOpen.value=true;await searchCustomers()}
async function createOrder(){
 const validLine=(line:CrmSalesOrderLineCreateDto)=>line.description.trim()&&Number.isFinite(line.quantity)&&line.quantity>0&&Math.abs(line.quantity*10000-Math.round(line.quantity*10000))<1e-8&&Number.isFinite(line.unitPrice)&&line.unitPrice>=0&&Number.isFinite(line.discountRate)&&line.discountRate>=0&&line.discountRate<=100&&Number.isFinite(line.taxRate)&&line.taxRate>=0&&line.taxRate<=100
 if(!form.value.orderNumber.trim()||!form.value.customerId.trim()||!form.value.orderDate||!/^[A-Za-z]{3}$/.test(form.value.currency.trim())||draftLines.value.length===0||draftLines.value.some(line=>!validLine(line))){toast.warning(t('crm.salesOrder.createRequired'));return}
 saving.value=true
 try{
  const input:CrmSalesOrderCreateDto={orderNumber:form.value.orderNumber.trim(),customerId:form.value.customerId.trim(),contactId:form.value.contactId.trim()||null,opportunityId:form.value.opportunityId.trim()||null,orderDate:form.value.orderDate+'T00:00:00',currency:form.value.currency.trim().toUpperCase(),customerPurchaseOrderNumber:form.value.customerPurchaseOrderNumber.trim()||null,paymentTerms:form.value.paymentTerms.trim()||null,deliveryTerms:form.value.deliveryTerms.trim()||null,notes:form.value.notes.trim()||null,lines:draftLines.value.map((line,index)=>({...line,productCode:line.productCode?.trim()||null,description:line.description.trim(),unit:line.unit?.trim()||null,sortOrder:index}))}
  await crmSalesOrderApi.create(input);toast.success(t('crm.salesOrder.created'));createOpen.value=false;await loadPage()
 }catch(e){toast.danger((e as Error)?.message||t('crm.salesOrder.createError'))}finally{saving.value=false}
}

async function loadPage(){loading.value=true;try{const p=createPageRequest({page:{pageIndex:pageIndex.value,pageSize}});const r=await crmSalesOrderApi.page({...p,keyword:keyword.value.trim()||null,status:status.value===''?null:status.value});rows.value=r.items;totalCount.value=r.page.totalCount}catch(e){toast.danger((e as Error)?.message||t('crm.salesOrder.loadError'))}finally{loading.value=false}}
async function openLines(row:CrmSalesOrderListItemDto){selected.value=row;lines.value=[];try{const p=createPageRequest({page:{pageIndex:1,pageSize:500}});const [detail,r]=await Promise.all([crmSalesOrderApi.detail(row.basicId),crmSalesOrderApi.lines({...p,salesOrderId:row.basicId})]);selected.value=detail||row;lines.value=r.items}catch(e){toast.danger((e as Error)?.message||t('crm.salesOrder.linesError'))}}
async function changeStatus(row:CrmSalesOrderListItemDto,next:CrmSalesOrderStatus){try{await crmSalesOrderApi.changeStatus({id:row.basicId,status:next});toast.success(t('crm.salesOrder.statusSaved'));await loadPage()}catch(e){toast.danger((e as Error)?.message||t('crm.salesOrder.statusError'))}}
function label(s:number){return t(`crm.salesOrder.status${s}`)}
onMounted(loadPage)
</script>
<template><main class="crm-workflow-page"><header class="page-header"><div><h1>{{t('crm.salesOrder.title')}}</h1><p>{{t('crm.salesOrder.description')}}</p></div><button v-if="canCreate" class="primary-button" @click="openCreate">{{t('crm.salesOrder.create')}}</button></header><section class="toolbar"><input v-model="keyword" :placeholder="t('crm.salesOrder.search')" @keydown.enter="pageIndex=1;loadPage()"><select v-model="status"><option value="">{{t('crm.salesOrder.allStatuses')}}</option><option v-for="s in [0,1,2,3,4,5]" :key="s" :value="s">{{label(s)}}</option></select><button @click="pageIndex=1;loadPage()">{{t('crm.salesOrder.query')}}</button><button :disabled="loading" @click="loadPage">{{t('crm.salesOrder.refresh')}}</button></section><section class="table-wrap"><div v-if="loading&&!rows.length" class="empty">{{t('crm.salesOrder.loading')}}</div><div v-else-if="!rows.length" class="empty">{{t('crm.salesOrder.empty')}}</div><table v-else><thead><tr><th>{{t('crm.salesOrder.number')}}</th><th>{{t('crm.salesOrder.customer')}}</th><th>{{t('crm.salesOrder.date')}}</th><th>{{t('crm.salesOrder.status')}}</th><th>{{t('crm.salesOrder.total')}}</th><th>{{t('crm.salesOrder.actions')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.basicId"><td>{{row.orderNumber}}</td><td>{{row.customerNameSnapshot}} (#{{row.customerId}})</td><td>{{new Date(row.orderDate).toLocaleDateString()}</td><td>{{label(row.status)}}</td><td>{{row.grandTotal.toLocaleString()}} {{row.currency}}</td><td class="actions"><button @click="openLines(row)">{{t('crm.salesOrder.viewLines')}}</button><button v-if="canExecute&&row.status===CrmSalesOrderStatus.Draft" @click="changeStatus(row,CrmSalesOrderStatus.Confirmed)">{{t('crm.salesOrder.confirm')}}</button><button v-if="canExecute&&row.status===CrmSalesOrderStatus.Confirmed" @click="changeStatus(row,CrmSalesOrderStatus.Processing)">{{t('crm.salesOrder.start')}}</button><button v-if="canExecute&&(row.status===CrmSalesOrderStatus.Draft||row.status===CrmSalesOrderStatus.Confirmed)" @click="changeStatus(row,CrmSalesOrderStatus.Cancelled)">{{t('crm.salesOrder.cancelOrder')}}</button></td></tr></tbody></table></section><footer class="pagination"><span>{{t('crm.salesOrder.totalCount',{count:totalCount})}} · {{t('crm.salesOrder.page',{current:pageIndex,total:totalPages})}}</span><div><button :disabled="pageIndex<=1||loading" @click="pageIndex--;loadPage()">{{t('crm.salesOrder.previous')}}</button><button :disabled="pageIndex>=totalPages||loading" @click="pageIndex++;loadPage()">{{t('crm.salesOrder.next')}}</button></div></footer>
<div v-if="createOpen" class="modal-backdrop" @click.self="createOpen=false">
<section class="editor create-editor">
<header><h2>{{t('crm.salesOrder.createTitle')}}</h2><button type="button" :disabled="saving" @click="createOpen=false">×</button></header>
<form @submit.prevent="createOrder">
<div class="form-grid">
<label>{{t('crm.salesOrder.number')}} *<input v-model="form.orderNumber" maxlength="40" required></label>
<label class="customer-picker">{{t('crm.salesOrder.customer')}} *<div class="picker-search"><input v-model="customerSearch" :placeholder="t('crm.salesOrder.customerSearch')" @keydown.enter.prevent="searchCustomers"><button type="button" @click="searchCustomers">{{t('crm.salesOrder.searchCustomers')}}</button></div><select v-model="form.customerId" required @change="loadCustomerRelations(form.customerId)"><option value="">{{t('crm.salesOrder.selectCustomer')}}</option><option v-for="customer in customerOptions" :key="customer.basicId" :value="String(customer.basicId)">{{customer.name}} (#{{customer.basicId}})</option></select></label>
<label>{{t('crm.salesOrder.contactId')}}<select v-model="form.contactId" :disabled="!form.customerId||loadingRelations"><option value="">{{t('crm.salesOrder.noContact')}}</option><option v-for="contact in contactOptions" :key="contact.basicId" :value="String(contact.basicId)">{{contact.fullName}} (#{{contact.basicId}})</option></select></label>
<label>{{t('crm.salesOrder.opportunityId')}}<select v-model="form.opportunityId" :disabled="!form.customerId||loadingRelations"><option value="">{{t('crm.salesOrder.noOpportunity')}}</option><option v-for="opportunity in opportunityOptions" :key="opportunity.basicId" :value="String(opportunity.basicId)">{{opportunity.name}} (#{{opportunity.basicId}})</option></select></label>
<label>{{t('crm.salesOrder.date')}} *<input v-model="form.orderDate" type="date" required></label>
<label>{{t('crm.salesOrder.currency')}} *<input v-model="form.currency" maxlength="3" required></label>
<label>{{t('crm.salesOrder.customerPo')}}<input v-model="form.customerPurchaseOrderNumber" maxlength="100"></label>
<label>{{t('crm.salesOrder.paymentTerms')}}<input v-model="form.paymentTerms" maxlength="500"></label>
<label>{{t('crm.salesOrder.deliveryTerms')}}<input v-model="form.deliveryTerms" maxlength="500"></label>
<label class="wide">{{t('crm.salesOrder.notes')}}<textarea v-model="form.notes" rows="2"></textarea></label>
</div>
<div class="line-heading"><h3>{{t('crm.salesOrder.lines')}}</h3><button type="button" :disabled="draftLines.length>=500" @click="addLine">{{t('crm.salesOrder.addLine')}}</button></div>
<div v-for="(line,index) in draftLines" :key="index" class="line-editor">
<label>{{t('crm.salesOrder.productCode')}}<input v-model="line.productCode"></label>
<label class="description-field">{{t('crm.salesOrder.descriptionLine')}} *<input v-model="line.description" maxlength="500" required></label>
<label>{{t('crm.salesOrder.quantity')}} *<input v-model.number="line.quantity" type="number" min="0.0001" step="0.0001" required></label>
<label>{{t('crm.salesOrder.unit')}}<input v-model="line.unit" maxlength="30"></label>
<label>{{t('crm.salesOrder.unitPrice')}} *<input v-model.number="line.unitPrice" type="number" min="0" step="0.0001" required></label>
<label>{{t('crm.salesOrder.discountRate')}}<input v-model.number="line.discountRate" type="number" min="0" max="100" step="0.0001"></label>
<label>{{t('crm.salesOrder.taxRate')}}<input v-model.number="line.taxRate" type="number" min="0" max="100" step="0.0001"></label>
<button type="button" class="remove-line" :disabled="draftLines.length===1" @click="removeLine(index)">{{t('crm.salesOrder.removeLine')}}</button>
</div>
<div class="total-preview">{{t('crm.salesOrder.estimatedTotal')}}: <strong>{{previewTotal.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}} {{form.currency.toUpperCase()}}</strong><small>{{t('crm.salesOrder.serverTotalNotice')}}</small></div>
<footer class="form-actions"><button type="button" :disabled="saving" @click="createOpen=false">{{t('crm.salesOrder.cancelForm')}}</button><button type="submit" class="primary-button" :disabled="saving">{{saving?t('crm.salesOrder.saving'):t('crm.salesOrder.save')}}</button></footer>
</form></section></div><div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="editor"><header><h2>{{selected.orderNumber}} · {{t('crm.salesOrder.lines')}}</h2><button @click="selected=null">×</button></header><p>{{selected.customerNameSnapshot}} · {{label(selected.status)}}</p><div v-if="'subtotal' in selected" class="order-detail-grid"><span>{{t('crm.salesOrder.customerPo')}}: {{selected.customerPurchaseOrderNumber||'—'}}</span><span>{{t('crm.salesOrder.contactId')}}: {{selected.contactId||'—'}}</span><span>{{t('crm.salesOrder.opportunityId')}}: {{selected.opportunityId||'—'}}</span><span>{{t('crm.salesOrder.paymentTerms')}}: {{selected.paymentTerms||'—'}}</span><span>{{t('crm.salesOrder.deliveryTerms')}}: {{selected.deliveryTerms||'—'}}</span><span>{{t('crm.salesOrder.subtotal')}}: {{selected.subtotal.toLocaleString()}} {{selected.currency}}</span><span>{{t('crm.salesOrder.discountTotal')}}: {{selected.discountTotal.toLocaleString()}} {{selected.currency}}</span><span>{{t('crm.salesOrder.taxTotal')}}: {{selected.taxTotal.toLocaleString()}} {{selected.currency}}</span><span>{{t('crm.salesOrder.notes')}}: {{selected.notes||'—'}}</span></div><div class="table-wrap"><table><thead><tr><th>{{t('crm.salesOrder.product')}}</th><th>{{t('crm.salesOrder.quantity')}}</th><th>{{t('crm.salesOrder.reserved')}}</th><th>{{t('crm.salesOrder.shipped')}}</th><th>{{t('crm.salesOrder.remaining')}}</th></tr></thead><tbody><tr v-for="line in lines" :key="line.basicId"><td>{{line.productCode||line.description}}</td><td>{{line.quantity}}</td><td>{{line.reservedQuantity}}</td><td>{{line.shippedQuantity}}</td><td>{{line.remainingQuantity}}</td></tr></tbody></table></div></section></div></main></template>
<style scoped>
.crm-workflow-page{display:flex;flex-direction:column;gap:16px;min-height:100%;padding:20px;color:hsl(var(--foreground))}.page-header,.toolbar,.pagination,.editor header{display:flex;align-items:center;justify-content:space-between;gap:12px}.page-header h1,.editor h2{margin:0;font-size:20px}.page-header p{margin:5px 0 0;color:hsl(var(--muted-foreground));font-size:12px}button,input,select{font:inherit}button{border:1px solid hsl(var(--border));border-radius:7px;padding:7px 11px;background:hsl(var(--card));cursor:pointer}.toolbar{justify-content:flex-start;flex-wrap:wrap}.toolbar input,.toolbar select{border:1px solid hsl(var(--border));border-radius:7px;padding:8px 10px;background:hsl(var(--card));color:inherit}.table-wrap{overflow:auto;border:1px solid hsl(var(--border));border-radius:10px;background:hsl(var(--card))}table{width:100%;border-collapse:collapse;min-width:760px;text-align:left;font-size:13px}th,td{padding:11px 12px;border-bottom:1px solid hsl(var(--border))}th{color:hsl(var(--muted-foreground));font-size:11px}.actions{white-space:nowrap}.actions button{margin-right:4px;font-size:11px}.primary-button{background:hsl(var(--primary));color:hsl(var(--primary-foreground));border-color:hsl(var(--primary))}.create-editor{width:min(1050px,100%)}.create-editor form{display:flex;flex-direction:column;gap:16px;margin-top:16px}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.form-grid label,.line-editor label{display:flex;flex-direction:column;gap:5px;font-size:12px;color:hsl(var(--muted-foreground))}.form-grid input,.form-grid textarea,.line-editor input{min-width:0;width:100%;box-sizing:border-box;border:1px solid hsl(var(--border));border-radius:6px;padding:8px;background:hsl(var(--background));color:inherit}.form-grid .wide{grid-column:1/-1}.picker-search{display:flex;gap:5px}.picker-search input{flex:1;min-width:0}.picker-search button{white-space:nowrap}.line-heading{display:flex;align-items:center;justify-content:space-between}.line-heading h3{margin:0;font-size:15px}.line-editor{display:grid;grid-template-columns:1fr 2fr 1fr 1fr 1fr 1fr 1fr auto;gap:8px;align-items:end;padding:12px;border:1px solid hsl(var(--border));border-radius:8px}.line-editor label{min-width:0}.line-editor input{padding:7px 6px}.remove-line{white-space:nowrap;color:hsl(var(--destructive))}.total-preview{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.total-preview small{color:hsl(var(--muted-foreground))}.form-actions{display:flex;justify-content:flex-end;gap:8px}@media(max-width:900px){.line-editor{grid-template-columns:repeat(3,minmax(0,1fr))}.description-field{grid-column:span 2}}@media(max-width:680px){.form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.line-editor{grid-template-columns:repeat(2,minmax(0,1fr))}}.empty{padding:44px;text-align:center;color:hsl(var(--muted-foreground))}.pagination{font-size:12px;color:hsl(var(--muted-foreground))}.pagination div{display:flex;gap:6px}.order-detail-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:14px 0;font-size:12px;color:hsl(var(--muted-foreground))}@media(max-width:680px){.order-detail-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}.modal-backdrop{position:fixed;z-index:1000;inset:0;display:grid;place-items:center;padding:20px;background:rgb(0 0 0 / 42%)}.editor{width:min(900px,100%);max-height:90vh;overflow:auto;border:1px solid hsl(var(--border));border-radius:12px;padding:20px;background:hsl(var(--card))}@media(max-width:680px){.crm-workflow-page{padding:12px}}
</style>
